// อ่าน expense items ทั้งหมดจาก node ก่อนหน้า (Google Sheets)
const items = $input.all();

// รวมยอดตามหมวด
const byCategory = {};
let grandTotal = 0;

for (const item of items) {
  const row = item.json;
  const category = (row.category || 'ไม่ระบุ').toString().trim();
  const amount = Number(row.amount) || 0;

  if (!byCategory[category]) {
    byCategory[category] = { category, total: 0, count: 0 };
  }
  byCategory[category].total += amount;
  byCategory[category].count += 1;
  grandTotal += amount;
}

// แปลง object เป็น array เรียงจากมากไปน้อย
const categories = Object.values(byCategory).sort((a, b) => b.total - a.total);

// หาเดือนของข้อมูล (จาก date แรกที่เจอ)
const firstDate = items[0]?.json?.date || '';
const month = (firstDate.toString()).slice(0, 7); // "2026-05"

// สร้าง summary_text ให้ AI อ่าน
const summaryText = categories
  .map(c => `- ${c.category}: ${c.total.toLocaleString('th-TH')} บาท (${c.count} รายการ)`)
  .join('\n');

// คืนค่า 1 item ที่มีทุกอย่าง
return [{
  json: {
    month: month,
    grand_total: grandTotal,
    item_count: items.length,
    top_category: categories[0]?.category || 'n/a',
    top_category_total: categories[0]?.total || 0,
    categories: categories,
    summary_text: summaryText
  }
}];

